editorial:
Record +x at L and −x at R+1. A prefix sum of these changes gives the net addition at each index. Reserve one extra position so an update that reaches n can still write its end marker. Use long long for accumulated changes. Time O(n+q), space O(n).
~~~
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n, q; cin >> n >> q;
    vector<long long> a(n + 1), diff(n + 2);
    for (int i = 1; i <= n; ++i) cin >> a[i];
    while (q--) {
        int l, r; long long x; cin >> l >> r >> x;
        diff[l] += x;
        diff[r + 1] -= x;
    }
    long long delta = 0;
    for (int i = 1; i <= n; ++i) {
        delta += diff[i];
        cout << a[i] + delta << (i == n ? '\n' : ' ');
    }
}
